from docx import Document
from docx.shared import Pt, Inches, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT
from docx.oxml.ns import qn
from docx.oxml import OxmlElement
import re

doc = Document()
sec = doc.sections[0]
sec.left_margin = sec.right_margin = Inches(1)
sec.top_margin = sec.bottom_margin = Inches(1)
st = doc.styles["Normal"]
st.font.name = "Times New Roman"; st.font.size = Pt(11.5)
st.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
st.paragraph_format.space_after = Pt(6)
for lvl, sz in ((1, 13), (2, 12), (3, 11.5)):
    h = doc.styles["Heading %d" % lvl]
    h.font.name = "Times New Roman"; h.font.size = Pt(sz); h.font.bold = True
    h.font.color.rgb = RGBColor(0x1F, 0x2A, 0x44)
    h.element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    h.paragraph_format.space_before = Pt(12); h.paragraph_format.space_after = Pt(6)

def runs(p, text):
    # **bold** and *italic*
    parts = re.split(r"(\*\*[^*]+\*\*|\*[^*]+\*)", text)
    for part in parts:
        if not part: continue
        if part.startswith("**"):
            r = p.add_run(part[2:-2]); r.bold = True
        elif part.startswith("*"):
            r = p.add_run(part[1:-1]); r.italic = True
        else:
            p.add_run(part)
    return p

def P(text, align=None, indent=None, size=None):
    p = doc.add_paragraph(); runs(p, text)
    if align == "c": p.alignment = WD_ALIGN_PARAGRAPH.CENTER
    if align == "j": p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    if indent: p.paragraph_format.left_indent = Inches(indent)
    if size:
        for r in p.runs: r.font.size = Pt(size)
    return p

def H(text, lvl=1): return doc.add_heading(text, level=lvl)

def B(text, lvl=0):
    p = doc.add_paragraph(style="List Bullet" if lvl == 0 else "List Bullet 2"); runs(p, text); return p

def N(text):
    p = doc.add_paragraph(style="List Number"); runs(p, text); return p

def Q(text):
    p = doc.add_paragraph(); runs(p, text)
    p.paragraph_format.left_indent = Inches(0.5); p.paragraph_format.right_indent = Inches(0.4)
    for r in p.runs: r.font.size = Pt(10.5)
    return p

def shade(cell, color):
    tcPr = cell._tc.get_or_add_tcPr()
    sh = OxmlElement("w:shd"); sh.set(qn("w:val"), "clear"); sh.set(qn("w:color"), "auto"); sh.set(qn("w:fill"), color)
    tcPr.append(sh)

def T(headers, rows, widths=None, size=9.5):
    t = doc.add_table(rows=1, cols=len(headers)); t.style = "Table Grid"
    t.alignment = WD_TABLE_ALIGNMENT.CENTER
    for i, h in enumerate(headers):
        c = t.rows[0].cells[i]; c.text = ""
        r = c.paragraphs[0].add_run(h); r.bold = True; r.font.size = Pt(size)
        shade(c, "D9E2F3")
    for row in rows:
        cells = t.add_row().cells
        for i, v in enumerate(row):
            cells[i].text = ""
            lines = v.split("\n")
            for j, line in enumerate(lines):
                p = cells[i].paragraphs[0] if j == 0 else cells[i].add_paragraph()
                runs(p, line)
                p.paragraph_format.space_after = Pt(2)
                for r in p.runs: r.font.size = Pt(size)
            if v in ("Critical",): shade(cells[i], "F4CCCC")
            elif v == "High": shade(cells[i], "FCE5CD")
            elif v == "Medium": shade(cells[i], "FFF2CC")
            elif v == "Low": shade(cells[i], "D9EAD3")
    if widths:
        for row in t.rows:
            for i, w in enumerate(widths):
                row.cells[i].width = Inches(w)
    doc.add_paragraph()
    return t
